package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.scheduling.*;import com.rpb.reservation.workforce.scheduling.rules.*;import com.rpb.reservation.workforce.attendance.*;import com.rpb.reservation.workforce.approval.*;import com.rpb.reservation.workforce.leave.LeaveRepository;import com.rpb.reservation.workforce.calendar.CalendarRepository;import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.walkin.api.CurrentActor;import com.rpb.reservation.workforce.domain.WorkforceException;import static com.rpb.reservation.workforce.scheduling.rules.AttendanceRules.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class WorkforceAttendanceRulesPostgresTest extends WorkforcePostgresTest {
 SchedulingRepository scheduling;ScheduleService schedules;ShiftService shifts;AttendanceRepository attendance;AttendanceAccess attendanceAccess;ApprovalService approvals;ApprovalSources sources;RuleTemplateService templates;UUID employee,shift,schedule;CurrentActor staff;WorkforceAudit audit;Instant start=Instant.parse("2026-10-28T03:00:00Z"),end=start.plusSeconds(43200);
 AttendanceRules rules(String punch){return new AttendanceRules(1,List.of(new BreakRule("rest","中途休息","quota",null,null,120,punch,false)),5,5,0,"excess",List.of(new AnomalyRule("MISSING","缺卡",true,false),new AnomalyRule("ABSENCE","旷工",true,true),new AnomalyRule("LATE","迟到",true,true),new AnomalyRule("BREAK_OVER","超时",true,true)),null,null);}
 @BeforeEach void setupRules(TestInfo info){if(info.getTestMethod().orElseThrow().getDeclaringClass()!=WorkforceAttendanceRulesPostgresTest.class)return;var mapper=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules();var json=new WorkforceJson(mapper);audit=new WorkforceAudit(logs,mapper);scheduling=new SchedulingRepository(jdbc,json);schedules=proxy(new ScheduleService(access,scheduling,repository,audit,clock));shifts=proxy(new ShiftService(access,scheduling,audit));attendance=new AttendanceRepository(jdbc,json);attendanceAccess=new AttendanceAccess(access,repository,scheduling);sources=new ApprovalSources(attendance,new LeaveRepository(jdbc),new CalendarRepository(jdbc),json,Clock.fixed(end.plusSeconds(60),ZoneOffset.UTC));approvals=proxy(new ApprovalService(access,attendanceAccess,repository,scheduling,new ApprovalRepository(jdbc,json),sources,audit,Clock.fixed(end.plusSeconds(60),ZoneOffset.UTC)));templates=proxy(new RuleTemplateService(access,new RuleTemplateRepository(jdbc,json),audit));UUID account=account("store_staff",Set.of(store),Set.of("workforce.view"));staff=new CurrentActor(tenant,account,"staff",Set.of("store_staff"),Set.of("workforce.view"),Set.of(store));employee=UUID.randomUUID();employees.save(admin,store,employee,command(0,List.of(store),company,account,null));shift=UUID.randomUUID();shifts.save(admin,store,shift,new SchedulingDtos.ShiftWrite(0L,"11-23","11:00","23:00",false,"none",0,0,0,0,false,true,rules("optional")));schedule=UUID.randomUUID();schedules.save(admin,store,schedule,new SchedulingDtos.ScheduleWrite(0L,employee,shift,LocalDate.of(2026,10,28),"scheduled"));}
 ClockService clockAt(Instant time){return proxy(new ClockService(attendanceAccess,repository,scheduling,attendance,audit,Clock.fixed(time,ZoneOffset.UTC)));}
 @Test void templateAndReviewReadsHonorAllAppGateDenials(){for(var reason:List.of(com.rpb.reservation.appgate.domain.AppGateDenyReason.APP_DISABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.TENANT_APP_NOT_ENABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.STORE_APP_NOT_ENABLED)){doReturn(com.rpb.reservation.appgate.domain.AppGateDecision.deny("workforce",tenant,store,"workforce.view",reason)).when(gate).evaluate(any());assertThatThrownBy(()->templates.list(admin,store)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);assertThatThrownBy(()->approvals.detail(admin,store,schedule)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);}}
 @Test void foreignTemplateOriginCannotBeClaimedByAnOwnStoreShift(){var referenced=new AttendanceRules(1,List.of(),0,0,0,"full",List.of(),UUID.randomUUID(),1L);assertThatThrownBy(()->shifts.save(admin,store,shift,new SchedulingDtos.ShiftWrite(1L,"local","11:00","23:00",false,"none",0,0,0,0,false,true,referenced))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(404);}
 @Test void newRulesTakePrecedenceOverInactiveLegacyDurationFields(){var next=shifts.save(admin,store,shift,new SchedulingDtos.ShiftWrite(1L,"Short","11:00","15:00",false,"duration",60,360,0,0,false,true,new AttendanceRules(1,List.of(),0,0,0,"full",List.of(),null,null)));assertThat(next.rules()).isNotNull();assertThat(next.breakAfterMinutes()).isEqualTo(360);assertThat(new AttendanceCalculator().calculate(next,start,start,start.plusSeconds(14400),List.of(),false).workSeconds()).isEqualTo(14400);}
 @Test void boundBreakPunchPersistsRuleAndRejectsConflictingReplay(){clockAt(start).punch(staff,store,UUID.randomUUID(),new AttendanceDtos.ClockWrite(schedule,"IN"));UUID id=UUID.randomUUID();var c=new AttendanceDtos.ClockWrite(schedule,"BREAK_START","rest");var active=clockAt(start.plusSeconds(3600)).punch(staff,store,id,c);assertThat(active.breakStartedRuleId()).isEqualTo("rest");assertThat(clockAt(start.plusSeconds(3700)).punch(staff,store,id,c)).isEqualTo(active);assertThatThrownBy(()->clockAt(start.plusSeconds(3700)).punch(staff,store,id,new AttendanceDtos.ClockWrite(schedule,"BREAK_START","other"))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(409);clockAt(start.plusSeconds(9600)).punch(staff,store,UUID.randomUUID(),new AttendanceDtos.ClockWrite(schedule,"BREAK_END","rest"));clockAt(end).punch(staff,store,UUID.randomUUID(),new AttendanceDtos.ClockWrite(schedule,"OUT"));var session=attendance.bySchedule(tenant,schedule).orElseThrow();assertThat(session.breaks().getFirst().ruleId()).isEqualTo("rest");assertThat(new AttendanceCalculator().calculate(scheduling.find(tenant,schedule).orElseThrow().shift(),start,start,end,session.breaks(),false).workSeconds()).isEqualTo(37200);}
 @Test void missingCardRequiresExplicitAbsenceAndDoesNotCreateAttendanceOrMoneyDeductions(){var row=approvals.detail(admin,store,schedule).row();assertThat(row.findings()).extracting(ApprovalDtos.Finding::code).contains("MISSING").doesNotContain("ABSENCE");assertThatThrownBy(()->approvals.approve(admin,store,schedule,new ApprovalDtos.ApprovalWrite(0L,row.sourceFingerprint(),"核对无卡"))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(409);var decisions=List.of(new ApprovalDtos.ReviewDecision("MISSING","absence","已核实未上班"));var c=new ApprovalDtos.ApprovalWrite(0L,row.sourceFingerprint(),"核实旷工",decisions);var approved=approvals.approve(admin,store,schedule,c);assertThat(approved.workSeconds()).isZero();assertThat(approved.decisions()).isEqualTo(decisions);assertThat(approvals.approve(admin,store,schedule,c).version()).isEqualTo(1);assertThat(attendance.bySchedule(tenant,schedule)).isEmpty();var after=approvals.detail(admin,store,schedule).row();assertThat(after.issues()).isEmpty();assertThat(after.fullAttendanceStatus()).isEqualTo("ineligible");assertThat(after.requiresReview()).isFalse();}
 @Test void templateScopeRetryAndChangesDoNotAlterScheduledSnapshot(){UUID id=UUID.randomUUID();var c=new RuleTemplateService.Write(0L,"统一休息",true,rules("optional"));var saved=templates.save(admin,store,id,c);assertThat(templates.save(admin,store,id,c)).isEqualTo(saved);assertThat(templates.list(admin,sibling).items()).extracting(RuleTemplateRepository.Template::id).contains(id);assertThatThrownBy(()->templates.save(staff,store,id,c)).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(403);var before=scheduling.find(tenant,schedule).orElseThrow();templates.save(admin,store,id,new RuleTemplateService.Write(1L,"修订",false,rules("required")));assertThat(scheduling.find(tenant,schedule).orElseThrow()).isEqualTo(before);var foreign=new CurrentActor(UUID.randomUUID(),admin.actorId(),"staff",admin.roles(),admin.permissions(),admin.storeIds());assertThat(templates.list(foreign,store).items()).isEmpty();}
 @Test void failedReviewAuditRollsBackAndLateReviewRequiresDecision(){clockAt(start.plusSeconds(360)).punch(staff,store,UUID.randomUUID(),new AttendanceDtos.ClockWrite(schedule,"IN"));clockAt(end).punch(staff,store,UUID.randomUUID(),new AttendanceDtos.ClockWrite(schedule,"OUT"));var row=approvals.detail(admin,store,schedule).row();assertThat(row.findings()).extracting(ApprovalDtos.Finding::code).containsExactly("LATE");assertThatThrownBy(()->approvals.approve(admin,store,schedule,new ApprovalDtos.ApprovalWrite(0L,row.sourceFingerprint(),"确认",List.of(new ApprovalDtos.ReviewDecision("LATE","",""))))).isInstanceOf(WorkforceException.class).extracting("status").isEqualTo(400);doThrow(new IllegalStateException("audit failed")).when(logs).append(any(com.rpb.reservation.common.scope.StoreScope.class),any());assertThatThrownBy(()->approvals.approve(admin,store,schedule,new ApprovalDtos.ApprovalWrite(0L,row.sourceFingerprint(),"确认",List.of(new ApprovalDtos.ReviewDecision("LATE","excused","已核实原因"))))).isInstanceOf(IllegalStateException.class);assertThat(approvals.detail(admin,store,schedule).history()).isEmpty();}
 @Test void optionalReviewNotesPersistAsTextSnapshotsWithoutWeakeningDecisions(){
  clockAt(start.plusSeconds(360)).punch(staff,store,UUID.randomUUID(),new AttendanceDtos.ClockWrite(schedule,"IN"));clockAt(end).punch(staff,store,UUID.randomUUID(),new AttendanceDtos.ClockWrite(schedule,"OUT"));
  var row=approvals.detail(admin,store,schedule).row();
  var c=new ApprovalDtos.ApprovalWrite(0L,row.sourceFingerprint(),null,List.of(new ApprovalDtos.ReviewDecision("LATE","excused",null)));
  var saved=approvals.approve(admin,store,schedule,c);assertThat(saved.note()).isEmpty();assertThat(saved.decisions().getFirst().note()).isEmpty();assertThat(approvals.approve(admin,store,schedule,c).version()).isEqualTo(1);
  var presets=new com.rpb.reservation.workforce.approval.explanations.ReviewExplanationRepository(jdbc);var id=UUID.randomUUID();presets.save(tenant,new com.rpb.reservation.workforce.approval.explanations.ReviewExplanationRepository.Item(id,"LATE","已核实交通原因",true,1));
  var next=approvals.approve(admin,store,schedule,new ApprovalDtos.ApprovalWrite(1L,row.sourceFingerprint(),"",List.of(new ApprovalDtos.ReviewDecision("LATE","excused","已核实交通原因"))));
  presets.save(tenant,new com.rpb.reservation.workforce.approval.explanations.ReviewExplanationRepository.Item(id,"LATE","修改后的说明",false,2));
  assertThat(approvals.detail(admin,store,schedule).history().getFirst().decisions().getFirst().note()).isEqualTo("已核实交通原因");assertThat(next.version()).isEqualTo(2);
 }
}
